def cases():
    rows = []
    for category, family, world, previous, positive, negative in PAIRS:
        for expected, text in ((True, positive), (False, negative)):
            rows.append(dict(id=f"{category}_{family}_{int(expected)}", category=category,
                             family=family, split="challenge", world=world,
                             previous=previous, expected=expected, text=text))
    return rows
